def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count opponent's defections and last few moves
    opp_defects = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_defects += 1

    last_me, last_op = history[-1]

    # Near the end, exploit known cooperators
    if n >= 98:
        if opp_defects <= 1:
            return 'D'
        if last_op == 'C':
            return 'C'
        return 'D'

    # Pure cooperate if no defections yet, but punish immediately on first defection
    if opp_defects == 0:
        return 'C'

    # Check if opponent has just started defecting (first defection)
    if opp_defects == 1 and last_op == 'D':
        # immediate retaliation
        return 'D'

    # Detect long mutual defection trap: if we both defected last 2 rounds, try to break
    if n >= 2:
        if (history[-1][0] == 'D' and history[-1][1] == 'D' and
                history[-2][0] == 'D' and history[-2][1] == 'D'):
            # cooperate with moderate probability to escape
            if rng.random() < 0.4:
                return 'C'

    # If opponent defected last, retaliate unless they've been generally cooperative
    if last_op == 'D':
        # Forgiving if opponent defection rate is low
        defect_rate = opp_defects / n
        if defect_rate < 0.25 and rng.random() < 0.3:
            return 'C'
        return 'D'

    # Opponent cooperated last. If they've been mostly cooperative, cooperate.
    defect_rate = opp_defects / n
    if defect_rate < 0.35:
        return 'C'

    # Mixed opponent: reciprocate cooperation but occasionally defect to test
    if rng.random() < 0.15:
        return 'D'
    return 'C'
